CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.quotations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), number bigint GENERATED ALWAYS AS IDENTITY UNIQUE, client_name text NOT NULL, document jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.quotations TO authenticated;
GRANT ALL ON public.quotations TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.quotations_number_seq TO authenticated,service_role;
ALTER TABLE public.quotations ENABLE ROW LEVEL SECURITY;
CREATE POLICY quotation_read ON public.quotations FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY quotation_create ON public.quotations FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid());
CREATE POLICY quotation_update ON public.quotations FOR UPDATE TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY quotation_delete ON public.quotations FOR DELETE TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.quotation_stamp() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN RAISE EXCEPTION 'Owner cannot change'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER quotation_stamp BEFORE UPDATE ON public.quotations FOR EACH ROW EXECUTE FUNCTION public.quotation_stamp();
CREATE INDEX quotations_owner_idx ON public.quotations(owner_id,created_at DESC);